const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const startDate = '2019-05-01';
  const endDate = '2019-06-30';

  // Define two approximate regions for Northern and Southern Kenya
  // Northern Kenya (e.g., Marsabit, Turkana)
  const northernKenya = ee.Geometry.Rectangle([35, 2, 41, 5]); // [minX, minY, maxX, maxY]
  // Southern Kenya (e.g., Kajiado, Taita-Taveta)
  const southernKenya = ee.Geometry.Rectangle([35, -4, 41, -1]); // [minX, minY, maxX, maxY]

  // Scale for reduceRegion, chosen to avoid timeout for large regions
  const scale = 1000;

  // Function to mask clouds in Sentinel-2 L2A imagery
  function maskS2clouds(image) {
    const s2aCloudMask = image.select('SCL').remap(
      [8, 9, 10, 3, 7, 11], // Clouds, cirrus, cloud shadows, snow/ice
      [1, 1, 1, 1, 1, 1], // Map to 1 (mask)
      0 // Default to 0 (keep)
    );
    // Mask out pixels with values of 1 (clouds/shadows/etc.)
    return image.updateMask(s2aCloudMask.eq(0));
  }

  // Function to calculate NDVI
  function calculateNDVI(image) {
    return image.normalizedDifference(['B8', 'B4']).rename('NDVI').copyProperties(image, ['system:time_start']);
  }

  // Function to process a region
  async function processRegion(region, name) {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(region)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 70)); // Filter out very cloudy images initially

    const initialSize = await collection.size().getInfo();
    if (initialSize === 0) {
      console.log(`${name} Images: 0 (C1)`);
      return { val: null, pixels: 0, status: 'C1' };
    }

    // Apply cloud mask and NDVI calculation
    collection = collection.map(maskS2clouds).map(calculateNDVI);

    // Compute the median NDVI composite
    const medianNDVI = collection.median();

    // Check if the median image is empty after masking
    const pixelCount = await medianNDVI.select('NDVI')
      .reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      })
      .get('NDVI')
      .getInfo();

    if (pixelCount === 0 || pixelCount === null) {
      console.log(`${name} Images: ${initialSize} (Val: 0), Pixels: 0 (C2)`);
      return { val: null, pixels: 0, status: 'C2' };
    }

    // Calculate the mean NDVI over the region
    const meanNDVI = await medianNDVI.select('NDVI')
      .reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      })
      .get('NDVI')
      .getInfo();

    if (meanNDVI === null || isNaN(meanNDVI)) {
      console.log(`${name} Images: ${initialSize} (Val: None), Pixels: ${pixelCount} (C3)`);
      return { val: null, pixels: pixelCount, status: 'C3' };
    }

    console.log(`${name} Images: ${initialSize}, Val: ${meanNDVI.toFixed(3)}, Pixels: ${pixelCount}`);
    return { val: meanNDVI, pixels: pixelCount, status: 'OK' };
  }

  console.log(`Analyzing NDVI for May-June 2019`);

  const northernResult = await processRegion(northernKenya, 'Northern Kenya');
  const southernResult = await processRegion(southernKenya, 'Southern Kenya');

  // Check for C1, C2, C3 from either region
  if (northernResult.status !== 'OK') {
    if (northernResult.status === 'C1') { console.log('C1'); return; }
    if (northernResult.status === 'C2') { console.log('C2'); return; }
    if (northernResult.status === 'C3') { console.log('C3'); return; }
  }
  if (southernResult.status !== 'OK') {
    if (southernResult.status === 'C1') { console.log('C1'); return; }
    if (southernResult.status === 'C2') { console.log('C2'); return; }
    if (southernResult.status === 'C3') { console.log('C3'); return; }
  }

  // Final comparison
  if (northernResult.val < southernResult.val) {
    console.log('A'); // NDVI was lower in northern Kenya
  } else {
    console.log('B'); // NDVI was not lower in northern Kenya
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
